 "content": "from collections import deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append((color, cells))
    return comps


def _l_cue(color, cells):
    rs = [r for r, _ in cells]
    cs = [c for _, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    # A cue is an exact, thick-free L made of two perpendicular straight arms.
    corners = ((r0, c0), (r0, c1), (r1, c0), (r1, c1))
    for cr, cc in corners:
        arms = {(cr, c) for c in range(c0, c1 + 1)} | {(r, cc) for r in range(r0, r1 + 1)}
        if arms == cells and max(r1-r0, c1-c0) >= 4 and min(r1-r0, c1-c0) >= 2:
            # The missing quadrant is opposite the two arms' interior corner.
            return (color, cells, cr, cc, r0, r1, c0, c1)
    return None


def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    comps = _components(grid, bg)
    cues = [cue for color, cells in comps if (cue := _l_cue(color, cells)) is not None]
    if not cues:
        return out
    # The most extended L is the direction cue.
    color, cue_cells, cr, cc, r0, r1, c0, c1 = max(
        cues, key=lambda x: max(x[5]-x[4], x[7]-x[6])
    )
    # The empty quadrant is opposite the two arms from the L corner.
    open_up = cr == r1
    open_down = cr == r0
    open_left = cc == c1
    open_right = cc == c0
    candidates = []
    for other_color, cells in comps:
        if cells == cue_cells:
            continue
        eligible = set()
        for r, c in cells:
            if ((open_up and r < cr) or (open_down and r > cr)) and ((open_left and c < cc) or (open_right and c > cc)):
                eligible.add((r, c))
        if eligible:
            d = min(abs(r-cr) + abs(c-cc) for r, c in eligible)
            candidates.append((d, -len(eligible), other_color, cells))
    if not candidates:
        return out
    _, _, _, target = min(candidates)
    for r, c in target:
        out[r][c] = color
    return out


if __name__ == '__main__':
    pass
