from collections import deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append((color, cells))
    return comps


def _l_cue(color, cells):
    rs = [r for r, _ in cells]
    cs = [c for _, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    # A cue is an exact, thick-free L made of two perpendicular straight arms.
    corners = ((r0, c0), (r0, c1), (r1, c0), (r1, c1))
    for cr, cc in corners:
        arms = {(cr, c) for c in range(c0, c1 + 1)} | {(r, cc) for r in range(r0, r1 + 1)}
        if arms == cells and max(r1-r0, c1-c0) >= 4 and min(r1-r0, c1-c0) >= 1:
            # The missing quadrant is opposite the two arms' interior corner.
            return (color, cells, cr, cc, r0, r1, c0, c1)
    return None


def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    comps = _components(grid, bg)
    cues = [cue for color, cells in comps if (cue := _l_cue(color, cells)) is not None]
    if not cues:
        return out
    # Locate the largest connected motif and recolor the nearest component
    # that is a smaller shape fragment beside it using the motif's color.
    largest_color, largest_cells = max(comps, key=lambda item: len(item[1]))
    candidates = []
    for other_color, cells in comps:
        if cells == largest_cells or len(cells) >= len(largest_cells):
            continue
        distance = min(abs(r-a)+abs(c-b) for r,c in largest_cells for a,b in cells)
        candidates.append((distance, len(cells), cells))
    if candidates:
        target = min(candidates, key=lambda x: (x[0], -x[1]))[2]
        for r,c in target:
            out[r][c] = largest_color
    return out



